std::string result;
std::shared_ptr<Node> current = root;
char byte;
int bit_count = 0;

// Read bits one at a time
while (bit_count < encoded_length && infile.get(byte)) {
    // Process each bit in the byte (from MSB to LSB)
    for (int i = 7; i >= 0 && bit_count < encoded_length; i--) {
        int bit = (byte >> i) & 1;

        // Traverse the tree: 0 = left, 1 = right
        if (bit == 0) {
            current = current->left;
        } else {
            current = current->right;
        }

        // If we reach a leaf node
        if (current->left == nullptr && current->right == nullptr) {
            result += current->data;
            current = root; // Reset to root for next character
        }

        bit_count++;
    }
}

return result;

